<template><article class="news-card" @click="open"><div class="copy"><div class="meta"><span>{{ String(index + 1).padStart(2, '0') }}</span><b>LIVE</b></div><h3>{{title}}</h3><p>{{description}}</p><footer>{{source}} · {{news.publishTime||'刚刚更新'}}</footer></div><img class="thumb" :src="image" :alt="title" @error="replace"/></article></template>
<script setup>import{computed}from'vue';import{useRouter}from'vue-router';import{translateDescription,translateSource,translateTitle}from'../utils/newsTranslation';const props=defineProps({news:{type:Object,required:true},index:{type:Number,default:0}});const router=useRouter();const fallback=seed=>`https://picsum.photos/seed/nova-${encodeURIComponent(seed)}/640/480`;const image=computed(()=>props.news.image||fallback(props.news.id));const title=computed(()=>translateTitle(props.news.title));const description=computed(()=>translateDescription(props.news.description||'实时新闻报道，点击查看详情。'));const source=computed(()=>translateSource(props.news.author||'新闻资讯'));const replace=e=>e.target.src=fallback(`${props.news.id}-alt`);const open=()=>{if(props.news.isLive)sessionStorage.setItem(`live-news:${props.news.id}`,JSON.stringify({...props.news,image:image.value}));router.push(`/news/detail/${props.news.id}`)}</script>
<style scoped>.news-card{display:flex;gap:16px;padding:19px 2px;border-bottom:1px solid rgba(255,255,255,.12);cursor:pointer}.copy{flex:1;min-width:0}.meta{display:flex;gap:8px;align-items:center;color:#a98eff;font-size:11px;font-weight:800}.meta b{font-size:9px;padding:3px 5px;border-radius:4px;background:#eee8ff;color:#7355e9}.copy h3{margin:6px 0;font-size:17px;line-height:1.4;color:#f6f7ff;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.copy p{margin:0 0 9px;color:#b6bad0;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.copy footer{font-size:11px;color:#9096b3}.thumb{width:132px;height:92px;object-fit:cover;border-radius:15px;flex:none;background:#292b42}</style>
